# Secrets copied from GitHub environments into the Vercel project by
# .github/workflows/sync-vercel-secrets.yml. Names only, never values.
# Editing this file runs the sync; so does "Run workflow" on the Actions tab.
#
# <GitHub environment>  <GitHub secret>       <Vercel variable>     [format]  [Vercel targets]
#   format: raw (default) | evm-key (0x + 64 hex; accepts Hedera DER keys)
#   targets: comma-separated, default production,preview
#
# VERCEL_TOKEN is read from the same environment or the repository secrets.

hedera-testnet  HEDERA_OPERATOR_KEY   TRUST_RELAYER_KEY     evm-key
hedera-testnet  HEDERA_OPERATOR_KEY   HEDERA_OPERATOR_KEY   evm-key
hedera-testnet  HEDERA_OPERATOR_ID    HEDERA_OPERATOR_ID
